from collections import defaultdict

def find_set(x):
    if parent[x] != x:
        parent[x] = find_set(parent[x])
    return parent[x]

def union(x, y):
    px, py = find_set(x), find_set(y)
    if px != py:
        parent[py] = px

def kruskal(graph):
    parent = defaultdict(lambda: next(idx))
    for v in range(1, len(graph)+1):
        parent[v] = v
    for v, edges in graph:
        min_edge = (float('inf'), float('inf'))
        u, v = next((u, v) for u, v in edges if u < v)
        steps_count = 0
        while True:
            steps_count += 1
            if steps_count > 2:
                break
            for u, v, _ in edges:
                if v == u:
                    continue
                if find_set(u) == find_set(v):
                    continue
                if steps_count == 2:
                    min_edge = (min(min_edge, (steps_count, (u, v))), (u, v))
                union(u, v)
                break
        if min_edge:
            union(min_edge[1][0], min_edge[1][1])
    for u, v, d in edges:
        if d > 2:
            union(v, u)
    return [find_set(u) for u, v, d in edges]

