        for j in range(m):
            sums[m*(i//n) + m*(i%n) + j + (char_to_alphabet[string[j]] * n)] += 1

    odd_prefixes = [0] * (m + 1)
    even_prefixes = [0] * (m + 2)  # odd as always, even becomes odd + even + odd

    for i in range(m):
        odd_prefixes[i + 1] += odd_prefixes[i]
        odd_prefixes[m + 1] += odd_prefixes[i+1]
        even_prefixes[i + 1] += even_prefixes[i]
        if i % 2 == 0:
            even_prefixes[i + 1] += even_prefixes[i]
        else:
            even_prefixes[i + 1] += even_prefixes[i] + 1

    odd_min_sum = odd_prefixes[-1]
    even_min_sum = even_prefixes[-1]

    for end in range(m):
        odd_sums = [100000000] * (4*m)
        even_sums = [1000000004] * (4*m)

        for mid in range(end + 1, 4*m):
            if mid % 2 == 0:
                odd_sums[mid] = odd_sums[mid - 2] + odd_sums[mid - 1] + even_prefixes[mid + 1]
                even_sums[mid] = even_prefixes[mid] + even_prefixes[mid + 1]
            else:
                odd_sums[mid] = odd_prefixes[2*m + mid - 2] + odd_prefixes[2*m + mid - 1] + odd_prefixes[mid] + odd_sums[mid - 1]
                even_sums[mid] = even_prefixes[mid] + odd_prefixes[mid - 1] + even_prefixes[mid + 1] + even_prefixes[2*m + mid - 1]

