from collections import deque

def solve_queries(A, B, Q, queries):
    max_A = A[:]
    for query in queries:
        t, l, r = query
        if t == 1:
            max_A[l-1] = max(max_A[l-1], A[l-1] + A[l]) if l <= r else max(A[l:r+1])
        elif t == 2:
            for i in range(l-1, r):
                A[i] += B[i]
        elif t == 3:
            x = calculate(B, i, l-1, r)
            for i in range(l-1, r):
                A[i] += x
        elif t == 4:
            x = calculate(A, i, l-1, r)
            for i in range(l-1, r):
                B[i] += x
    return max_A

def calculate(arr, n, l, r):
    q = deque([0])  # initialize queue for range queries
    for i in range(l-1, r):
        while q[0] < i - 1 and (q[0] + 1) in arr:
            q[0] += 1
        while q and i - 1 - q[-1] > n or q[-1] < arr[i-1]:
            q.pop()
        q.append(i - 1)
    return q[0]

