def update_sequence(seq, changes):
    for i, change in enumerate(changes):
        seq[i] += change
    return seq

def query(max_elements, elements, start, end):
    return max(max_elements[start:end+1]) if elements[start:end+1] else max_elements[end+1]

def process_queries(N, Q, A, B, queries):
    max_elements = [max(A), max(B)]
    for t, l, r in queries:
        if t == 1:
            max_elements = update_sequence(max_elements, (A[l-1], B[l-1]))
        elif t == 2:
            A[l-1:r] += B[l-1:r]
            B = [x+B[i] for i, x in enumerate(B)]
        elif t == 3:
            A[l-1:r] += B[r-l]
        elif t == 4:
            A[l-1:r] += B
    return max_elements

