def is_game_win(battlefield):
    n, m = len(battlefield), len(battlefield[0])

    def is_legal_move(x, y):
        for dx, dy in (1, -1), (0, 1), (-1, 0), (1, -1):
            steps = 0
            nx, ny = x + dx, y + dy
            while 0 <= nx < n and 0 <= ny < m:
                if battlefield[nx][ny] in 'LR':
                    return False
                steps += 1
                nx += dx
                ny += dy
        return True

    # Check if any legal move leads to an active cell
    while any([not is_legal_move(x, y) for x in range(n) for y in range(m)]):
        for x in range(n):
            for y in range(m):
                if battlefield[x][y] == 'X':
                    battlefield.pop(x)
                    if len(battlefield) == 0:
                        battlefield.append(['X'] * m)
        for y in range(m):
            for x in range(n - 1, -1, -1):
                if battlefield[x][y] == 'X':
                    battlefield[~x].pop(y)

    return 'WIN' if 'X' not in battlefield[0] else 'LOSE'

