def convex_hull(points):
    lower = []
    upper = []

    # Lower part of the hull
    lower_points = sorted(points)[:2]
    while points:
        point = points.pop()
        if point[1] >= lower_points[0][1]:
            lower.append(point)
            continue
        while lower and point[1] >= lower[-1][1]:
            lower.pop()
        lower.insert(0, point)
        upper = []
        # Upper part of the hull
        if point[1] < lower_points[1][1]:
            while points and point[1] >= points[-1][1]:
                point = points.pop()
            while upper and point[1] < upper[-1][1]:
                upper.pop()
            upper.append(point)

    return lower, upper

