from collections import deque
from typing import List

def solve(n: int, regions: List[List[int]]) -> List[int]:
    delays = deque()
    for sheep, likes in regions:
        current = [sheep, sheep]
        for like in likes:
            current[0], current[1] = current[1], like
        delays.append(tuple(current))
    second_pair = None
    for sheep, like in regions:
        if like == sheep:
            second_pair = (sheep, likes[0])
    second = (second_pair[1], second_pair[1])
    while delays:
        pos, sheep = delays.pop()
        if sheep[0] < second[0]:
            sheep, second = second, sheep
            first = (sheep[1], second[1])
        pair = (largest_pos(second), largest_pos(sheep))
        if first != pair:
            first, pair = pair, first
        region = sorted([first[0], pair[0], double_lamda(max(first[1], pair[1]), lambd(max(sheep[0], pair[0]), pos))])
        first = sorted([region[1], first[1] if first[1] == pair[1] else region[1]])
        sheep = sorted([region[1], sheep[1] if sheep[1] == pair[1] else region[1]])
        if first[0] >= sheep:
            first.append(pair[1])
            sheep.append(pair[0])
        for first_pos, sheep_pos in zip(first[:-1], sheep[:-1]):
            region[0:0] = [second_pos := (first_pos, second_pos), first_pos, sheep_pos]
    return region

def double_lamda(x, y):
    return round((x - y) / (x + y), 8)

def lambd(x, y):
    return abs(x - y)

def largest_pos(pos):
    return pos[1] if pos[1] < pos[0] else pos[1]
