```python
import collections
import sys

# Simulate the game's executions, Misha's messages, and the friends' states
class LakeGame:
    def __init__(self, players, turns):
        self.players = sorted(players)  # Sort players by their indices
        self.turns = turns  # Total number of turns
        self.size = len(players)  # Number of players
        self.completed = False  # Flag to check if players are at the finish vertex

    def move(self, turn, i, target):
        # Print the move command
        print(f"next {turn} {i} {target}")
        # Flush the output to ensure the message is sent immediately
        sys.stdout.flush()

    def receive(self, messages):
        for mes in messages:
            # Parse the messages to extract the player groups
            groups = collections.defaultdict(list)
            group_prefix = ''
            for i in range(len(mes)):
                if mes[i] == ' ':
                    groups[group_prefix].append(int(mes[i - 1:i]))
                elif mes.startswith(group_prefix):
                    group_prefix = mes[i:]
            vertices = list(groups.values())
            # Find the vertex with the most beautiful view
            best_vertex = None
            for v in vertices:
                for k in v:
                    if best_vertex is None or sum(v[k]) > sum(best_vertex[k]):
                        best_vertex = v

            # Send a query to get the status of the vertices
            print(f"next {turn + 1} {" ".join(map(str, range(self.size)))}")
            sys.stdout.flush()

            # Parse the received messages
            group_status = [0] * self.size
            for k in best_vertex:
                for g in groups[k]:
                    group_status[g] |= 1 << k
            query_status = dict.fromkeys(groups.keys(), -1)

            # Update players' states
            for i, mi in enumerate(mes):
                for j in groups[str(mi)]:
                    groups[str(j)][i] &= 0

            # Check if the game is won
            if all(sum(v) == 1 for v in query_status.values()): 
                self.completed = True
                return

    def run(self):
        while not self.completed:
            for i in range(self.size):
                self.move(0, i, i)
            self.receive([sys.stdin.readline().strip()])
        print("done")
        sys.stdout.flush()

if __name__ == "__main__":
    t = int(input().strip())  # Number of vertices in the path
    c = int(input().strip())  # Number of vertices along the coast
    game = LakeGame(c, t + c)
    game.run()
