def can_win(board):
    """
    Determines if Roma can win given the current board configuration.
    """
    rows, cols = len(board), len(board[0])

    def is_lost(row, col):
        """
        Checks if the current play leads to being lost.
        """
        for dr, dc in [(1, -1), (-1, 1), (1, 1), (-1, -1)]:
            r, c = row + dr, col + dc
            if r < 0 or r >= rows or c < 0 or c >= cols or board[r][c] == 'R':
                return True
        return False

    def move_to_x(row, col):
        """
        Performs the diagonal move laterally.
        """
        board[row][col] = 'X'
        for dr, dc in [(1, -1), (-1, 1), (1, 1), (-1, -1)]:
            r, c = row + dr, col + dc
            while r < 0 or r >= rows or c < 0 or c >= cols or board[r][c] == 'L':
                r, c = row + dr, col + dc
            board[r][c] = 'L'

    visited = [[False] * cols for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            if board[r][c] == 'X':
                if not visited[r][c]:
                    if is_lost(r, c):
                        return 'LOSE'
                    moved_l = False
                    while board[r][c] == 'L':
                        board[r][c] = 'X'
                        if not moved_l and not is_lost(r, c):
                            move_to_x(r, c)
                        moved_l = True
                    while moved_l and not is_lost(r, c):
                        board[r][c] = 'L'
    return 'WIN'

