def magical_wave_progress(start):
    """Determines what happens to the cells in the diagonal wave when a cell is hit."""
    progress = 1
    dx, dy = start[1] - 1, start[0] - 2
    for i in range(1, len(start)):
        current = 0
        while dx >= 0 and dy < len(start) - 1:
            dx, dy = dx - 1, dy + 1
            current += 1
        if dx == 0:
            dx, dy = 1, current - 1
        progress = (progress * i) // current
    return progress

def calculate_opponent_wins(from_, to_, row_, col_):
    """Calculates the number of winning options for the opponent in a given row."""
    return max(0, from_ + (to_ - from_) * (len(row_) - 1 - col_))

def calculate_opponent_wins_all(row_):
    """Calculates all opponent wins for the given part of the field."""
    return row_.count("R") + row_.count("L") - min(row_.count("L"), row_.count("R")) + 1

def determine_winner():
    """Determines if Roma can guarantee a win or not based on the given field."""
    field = input().split()
    column = [0] * len(field)
    for i in range(len(field)):
        for j in range(len(field[i])):
            column[j] += field[i][j] == "L"
            column[len(field) - j - 1] += field[i][j] == "R"
    best_field = [column[i] for i in range(len(field))]
    to_fill = 0 if best_field[0] == "X" else 1
    spaces = length - 1 + to_fill
    row = best_field.index("L")
    for i in range(len(field)):
        for _, j_ in enumerate(best_field):
            if best_field[j_] == "X":
                to_fill += j_ == spaces
                space = best_field.index("X")
            else:
                spaces, to_fill = spaces + magical_wave_progress(i + space - row - spaces), 1
