                merged.append(s1[i][:len(s1[i])])
                i += 1
            else:
                merged.append(s2[j][:len(s1[i])])
                j += 1
    merged.extend(s1[i:])
    merged.extend(s2[j:])
    return merged

def find_max_subsequence_length(A, K, W, permutation):
    subsequences = [A[i:i+K] for i in range(len(A)-K+1)]
    max_length = 0
    for i in range(K-1):
        for j in range(i+1, K):
            merged = merge_subsequences(subsequences[i], subsequences[j], permutation)
            if is_nth_increasing_ons(merged):
                max_length = max(max_length, len(merged))
    return dist(max_length, W)

def is_nth_increasing_ons(sequence):
    n = len(sequence)
