from collections import defaultdict

def find(graph, x):
    while x != graph[x]:
        x = graph[x]
    return x

def union(graph, parent, child):
    rootX = find(graph, parent)
    rootY = find(graph, child)
    if rootX < rootY:
        graph[rootY] = rootX
    else:
        graph[rootX] = rootY

def member_next(graph, x, steps):
    strong = find(graph, x)
    nextx = x + steps if steps > 0 else x - (steps * (-1))
    while member(graph, nextx) != strong:
        nextx += steps if steps > 0 else steps * (-1)
    return nextx

def graph_search(vertices):
    graph = defaultdict(list)
    for x, y in vertices:
        graph[x].append(y)
    parents = {}
    for node in vertices:
        parents[node] = node
        for neighbor in graph[node]:
            parent = find(graph, node)
            union(graph, neighbor, parents[neighbor])
    return graph, parents

def calculate_points(vertices, k):
    graph, parents = graph_search(vertices.copy())
    visited = set()
    points = defaultdict(int)

    def dfs(graph, parent, points, visited, k, i):
        if i > k:
            return
        for neighbor in graph[i]:
            if neighbor not in visited:
                visited.add(neighbor)
                dfs(graph, parent, points, visited, k, neighbor)
                if find(graph, neighbor) == find(graph, parent):
                    points[parent] += 1
        return

    dfs(graph, 'start', points, visited, k, 'start')
    return points['start'] > points['end']

def calculate_winning_round(board):
    k = 3
    w = 7
    points = calculate_points(board, k)
    your_wins = w % 2 == points[k]
    return 'Malek' if not your_wins else 'Hamed'

