            max_score += A[i]
        elif A[i] > A[max_ind]:
            max_score += A[i]
            max_ind = i
        else:
            S += A[i]
        if max_score - S < 0:
            if max_score > 0 and A[i] != A[max_ind]:
                S -= A[i]
            continue
        total = np.partition(A, [max_ind][::-1], kind='heapsort')[::-1]
        if max_score - S == A[i]:
            # Check if max_ind is not the index of the second maximum score
            if max_ind != second_max_score:
                Xs.append(max_score - 2 * S)
                second_max_score = -float('inf')
                max_score -= 2 * S
            S -= A[i]
        else:
            Xs.append(max_score - S)
            S -= A[i]
    return max(Xs)

