def build_graph(strings):
    graph = defaultdict(set)
    from collections import defaultdict

    from typing import Callable, Set

    class Node:
        def __init__(self, s: str):
            self.s, self.f = "0", False
            for c in s:
                if c != self.s[-1:]:
                    if len(self.s) >= 4:
                        return
                    self.s += c
            self.f = True

    from typing import Callable, Set, DefaultDict, Tuple, List

    def build_tree(root: Node, seen: Set[Node] = set()):
        stack = [root]
        seen |= {root}
        while visited := set():
            for node in visited:
                children, seen = (node.f for _ in [children], [*visited])
                node.f = True
                seen |= node.f
                for c in children + [f"{node.s}{i}" for i in range(1, len(node.s) * 2) if node.s not in seen]:
                    graph[node].add(c)
                    seen.add(c)
                visited -= [*children]
                visited |= seen

    built = {}

    for string in strings:
        root, node = Node(string), Node(string)
        node.s = string
        if string not in built:
            build_tree(Node(string[0]))
            continue
        if node not in built:
            root.f = root.s != string[0]
        if not root.f:
            build_tree(node)

    print(built)

