from bisect import bisect, bisect_left

def find_two_max(A):
    sorted_A = sorted(A, reverse=True)
    if sorted_A[0] >= sorted_A[1]:
        return sorted_A[0], sorted_A[1]
    return sorted_A[1], sorted_A[2]

def score_subarray(A, X, B):
    if bisect(A, X) > len(A) or bisect(A, X) - 1 < 0:
        return -sum(A)
    return sum(A) - sum(A[:bisect_right(A, X)])

def max_score_strategy(A, X):
    N = len(A)
    B = []
    total_score = 0
    for i in range(N):
        if total_score > 0:
            current_score = score_subarray(A, X, B)
            if type(current_score) is int:
                if total_score - current_score < 0:
                    B.append(A[i])
                else:
                    if current_score < 0:
                        B[-1] = max(B[-1], A[i])
                        B.pop(-2)
                    else:
                        B.append(max(B))  # Prefer adding any element here for maximizing the score
        else:
            B.append(A[i])
        current_score = score_subarray(B, X, A[i:])
        if type(current_score) is int:
            if current_score > 0 or total_score < 0:
                A[i] = current_score
                B = []
                total_score = current_score
            else:
                B.append(min(B))  # Reduce by simply taking the minimum value to make the score -ve
    return -sum(A)

