import random
from typing import List

def split_in_permutation(perm: List[int]) -> List[List[int]]:
    n = len(perm)
    for i in range(n, 1, -1):
        for j in range(i-1):
            if perm[j] > perm[i-1]:
                perm[j], perm[i-1] = perm[i-1], perm[j]
                break
        if j != i-1:
            return perm[:i], perm[i:]
    return [perm]

def create_original_permutation(seq: List[int]) -> List[int]:
    return seq

def construct_permutation(seq: List[int]) -> List[int]:
    n = len(seq)
    length = len(seq)
    permutations = []
    for p in permutations:
        subseqs = [split_in_permutation(seq[:length])]
        new_perm = create_original_permutation(seq[:length])
        length -= 1
        permutations.append(new_perm)
    return subseqs


def create_b_permulation(sequence: List[int]) -> List[int]:
    n = len(sequence)
    if n == 1:
        return (sequence[0])

    perm = create_permutation(sequence)
    B_perm = []
    for i in range(n):
        B_perm = B_perm + [perm[i][0]]
    return B_perm

def find_max_increasing_subsequence(length: int, sequence: List[int]) -> List[int]:
    increment = []
    for i in range(length - 1):
        if sequence[i + 1] < sequence[i]:
            max_num_i = find_max_increasing_subsequence(i, sequence)
            increment.append(max_num_i)
    return increment

def find_max_increasing_subsequence_for_testcase(seq: List[int]) -> List[int]:
    B_perm = create_b_permulation(seq)
    max_length = find_max_increasing_subsequence(len(seq), B_perm)
    return max_length

if __name__ == '__main__':
    N, K = map(int, input().split())
    sequence = list(map(int, input().split()))
    result = find_max_increasing_subsequence_for_testcase(sequence)
    print(*result)
