import math

def factorize(n):
    queries = []
    for i in range(2, n):
        quotient, remainder = divmod(i, n)
        if remainder == 0 and (i - n) % n == 0:
            queries.append((i, n))
            break
        if quotient != 1 and (quotient - 1) % n == 0:
            if quotient != 1:
                for j in range(2, quotient):
                    gcd = math.gcd(i, j*quotient)
                    if gcd > 1:
                        if gcd == 3:
                            queries.append((j, i // gcd))
                        else:
                            queries.append((3, gcd))
                            break
            else:
                if quotient != 1:
                    for j in range(2, quotient):
                        gcd = math.gcd(i, j*quotient)
                        if gcd > 1:
                            if gcd == 3:
                                queries.append((j, i // gcd))
                            else:
                                queries.append((3, gcd))
                                break
    return queries

