def can_win(board, player, used_rows, used_cols):
    stack = []
    for i in range(n):
        for j in range(m):
            if board[i][j] == player:
                stack.append([(i, j)])
    if len(stack) % 2 == 0:
        return True, stack
    else:
        for direction in [(0, 1), (1, 0), (-1, -1)]:
            init_row, init_col = stack[0][0]
            reachable = [init_row, init_col]
            nudge = init_row * init_col * direction
            for _ in range(len(stack) - 1):
                new_row, new_col = init_row + nudge // direction[0], init_col + nudge // direction[1]
                if 0 <= new_row < n and 0 <= new_col < m and board[new_row][new_col] != player:
                    new_row += nudge % direction[0]
                    new_col += nudge % direction[1]
                    reachable += [new_row, new_col] if board[new_row][new_col] == 'L' or 'R' else (new_row, new_col)
                    break
                stack.remove(stack.pop(0))
                row, col = stack.pop(0)
                init_row, init_col = row + direction[0], col + direction[1]
            reachable += stack
            stack = []
            for i in reachable:
                if board[i] != 'L' and 'R':
                    return False, p
                else:
                    stacks, player = can_win(board, board[i], reachable)         
                    if stacks or can_win(board, board[i], alpha) and alpha > player:
                        return True, stacks
                    else:
                        stacks, player = can_win(board, board[i], beta) 
                        if stacks or can_win(board, board[i], gamma) and gamma > player:
                            return True, stacks

def solve():
    if is_end(field, 'R'):
        return 'LOSE'
    win, moves = can_win(field, 'L', [], (n, m, 1))
    if win:
        return 'WIN'
    return solve()

