from typing import List

def is_point_on_convex_hull(x: int, y: int, hull: List[List[int]]) -> str:
    """
    Determines if a point (x, y) is on the convex hull of the given points.

    :param x: x-coordinate of the point
    :param y: y-coordinate of the point
    :param hull: list of points defining the convex hull
    :return: "YES" if on the hull, "NO" otherwise
    """
    def cross_product(p1: List[int], p2: List[int], p3: List[int]) -> int:
        return (p2[0] - p1[0]) * (p3[1] - p1[1]) - (p2[1] - p1[1]) * (p3[0] - p1[0])

    def on_hull(x, y, hull):
        return all(cross_product(hull[i], hull[(i + 1) % len(hull)], [x, y]) != 0 for i in range(len(hull)))

    hull_picked = []
    n = len(hull)

    for i in range(n):
        current = cross_product(hull[i], hull[(i + 1) % n], [x, y]) >= 0  # Determine the orientation
        current_correct = current and on_hull(x, y, hull[i:])  # If inscribed into hull
        hull_picked.append(current and current_correct)
        hull_picked.sort()
        if not current_picked:
            break

    return "YES" if not hull_picked else "NO"

def solve(q: int, points: List[List[int]], hull: List[List[int]]) -> None:
    hull.append(points[0])
    for point in points[1:]:
        found = False
        for i in range(len(hull)):
            if cross_product(hull[i], point, hull[(i + 1) % len(hull)]) > 0 or cross_product(hull[i], hull[(i + 1) % len(hull)], point) <= 0:
                hull.pop(i)
                break
        hull.append(point)
    print(is_point_on_convex_hull(points[0][0], points[0][1], hull))

def main():
    input_files = "test_a_input.txt", "test_b_input.txt", "test_c_input.txt"
    data_sets = [get_input(i) for i in input_files]
    for data in data_sets:
        num_queries, points, hull = data
        for i in range(len(points)):
            if i % 4 == 3:
                solve(num_queries // 4, points[i:i+4], hull)
        points.clear()
        hull.clear()

if __name__ == "__main__":
    main()
