import sys

def can_win(field):
    n, m = len(field), len(field[0])
    dp = [[[1 if i == j == 2 else 0 for _ in range(m)] for _ in range(n)] for _ in range((n + m) // 2)]

    for i in range(n):
        for j in range(m):
            for d in [1, 2]:
                if valid(i, j, d, field, n, m):
                    dp[i // (n + m // 2)][i % (n + m // 2)][d] = 1

    for k in range(n, n + m + 1):
        for d in [1, 2]:
            if dp[k // (n + m // 2)][k % (n + m // 2)][d]:
                for i in range(n):
                    for j in range(k - 1):
                        if valid(i, j, d, field, n, m):
                            dp[k // (n + m // 2)][k % (n + m // 2)][1 if d == 2 else 2] = 1
                return True

    return False

def valid(i, j, d, field, n, m):
    x1, y1 = i + d, j + d
    if x1 < 0 or x1 >= n or y1 < 0 or y1 >= m or field[x1][y1] not in ('L', 'R', 'X'):
        return False
    return (x1 - j, y1 - i) == (d, d)

if __name__ == '__main__':
    field = []
    for i in range(int(input())):
        field.append(input().strip())

    print('WIN' if can_win(field) else 'LOSE')
