def count_seconds_to_determine(n, original, codes):
    seconds = 0
    while True:
        for i, digit_code in enumerate(codes):
            original_digit = (int(str(original)[i]) - 1 + ord('a') - ord('#')) % 26
            if digit_code != codes[i][original_digit]:
